import 'package:accounting_software/app/features/catalog/genders/domain/entity/gender.dart'; class GenderModel { const GenderModel({required this.id,required this.name,required this.code,required this.isActive,required this.sortOrder}); final int id,sortOrder; final String name,code; final bool isActive; factory GenderModel.fromJson(Map<String,dynamic> j){final raw=j['id'];final id=raw is int?raw:int.tryParse(raw.toString());if(id==null)throw const FormatException('Invalid gender id');return GenderModel(id:id,name:j['name'] as String,code:j['code'] as String,isActive:j['is_active'] as bool? ??true,sortOrder:(j['sort_order'] as num?)?.toInt()??0);} Gender toEntity()=>Gender(id:id,name:name,code:code,isActive:isActive,sortOrder:sortOrder); }